use bevy::prelude::*;
use bevy_egui::{egui,EguiContexts,EguiPlugin,EguiPrimaryContextPass};
#[derive(Resource,Default)] struct HudInput([f32;2],bool,bool);
use forge_engine::{Project,Simulation,project_point};
use std::path::PathBuf;
#[derive(Resource)] struct Game{inventory:Option<forge_engine::Inventory>,inventory_open:bool,inventory_selected:Option<usize>,inventory_message:String,project:Project,sim:Simulation,original:Project,demo:Option<forge_engine::DemoSession>,root:PathBuf,level:usize,menu:bool,campaign:bool,finished:bool,#[cfg(feature="audio")] audio_revision:u64}
#[cfg(feature="audio")] #[derive(Component)] struct AudioBus {gain:f32,music:bool,source:uuid::Uuid,spatial:bool,distance:f32,last_volume:f32}
#[derive(Component)] struct ObjectId(uuid::Uuid);
fn main(){if std::env::args().nth(1).as_deref()==Some("--benchmark"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match forge_engine::performance::benchmark(&path,600){Ok(report)=>{println!("{report}");return;},Err(e)=>{eprintln!("{e}");std::process::exit(1);}}}if std::env::args().nth(1).as_deref()==Some("--smoke"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match Project::load(&path).and_then(|p|{forge_engine::modules::validate(&p)?;forge_engine::smoke(p)}){Ok(())=>{println!("SMOKE PASS");return;},Err(e)=>{eprintln!("SMOKE FAIL: {e}");std::process::exit(1);}}}let path=std::env::args_os().nth(1).map(PathBuf::from).unwrap_or_else(||PathBuf::from("project.forge.json"));let path=match path.canonicalize(){Ok(p)=>p,Err(e)=>{eprintln!("Project: {e}");std::process::exit(1);}};let p=match Project::load(&path){Ok(p)=>p,Err(e)=>{eprintln!("{e}");std::process::exit(1);}};if let Err(e)=forge_engine::modules::validate(&p){eprintln!("{e}");std::process::exit(1); }let folder=path.parent().unwrap().to_path_buf();let root=folder.to_string_lossy().into_owned();let campaign=folder.join("level2.forge.json").is_file() && folder.join("level3.forge.json").is_file() && path.file_name().is_some_and(|n|n=="project.forge.json");let mut app=App::new();app.insert_resource(Game{inventory:p.settings.inventory.clone(),inventory_open:false,inventory_selected:None,inventory_message:String::new(),project:p.clone(),sim:Simulation::default(),original:p.clone(),demo:(forge_engine::DemoSession::total(&p)>0).then(forge_engine::DemoSession::default),root:folder,level:1,menu:forge_engine::DemoSession::total(&p)>0,campaign,finished:false,#[cfg(feature="audio")] audio_revision:0}).add_plugins(DefaultPlugins.set(AssetPlugin{file_path:root,..default()}).set(ImagePlugin::default_nearest()).set(WindowPlugin{primary_window:Some(Window{title:p.name.clone(),resolution:(p.settings.production.resolution[0] as f32,p.settings.production.resolution[1] as f32).into(),..default()}),..default()})).add_plugins(EguiPlugin::default()).init_resource::<HudInput>().add_systems(EguiPrimaryContextPass,hud).add_systems(Startup,setup).add_systems(Update,(tick,particle_render).chain());#[cfg(feature="audio")] app.add_systems(Update,(sync_scene_audio,mix_audio).chain().after(tick));#[cfg(feature="lighting")] app.add_plugins((forge_engine::gpu_scene::GpuScenePlugin,forge_engine::gpu_particles::GpuParticlesPlugin)).add_systems(PostUpdate,(gpu_scene_sync,gpu_particles_sync).chain().before(bevy::transform::TransformSystem::TransformPropagate));app.run();}
fn setup(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>){commands.spawn(Camera2d);#[cfg(feature="audio")] commands.spawn((bevy::audio::SpatialListener::new(32.),Transform::default()));for o in &game.project.objects{if o.camera{continue;}let mut sprite=Sprite::from_color(Color::srgba_u8(o.color[0],o.color[1],o.color[2],o.color[3]),Vec2::from_array(o.size));if let Some(path)=&o.sprite{sprite.image=assets.load(path.clone());}commands.spawn((sprite,Transform::default(),ObjectId(o.id)));}}
/// A scene transition or explicit restart starts the scene's audio once, including one-shots.
#[cfg(feature="audio")]
fn sync_scene_audio(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>,voices:Query<Entity,With<AudioBus>>,mut revision:Local<Option<u64>>){
 if *revision==Some(game.audio_revision){return;} *revision=Some(game.audio_revision);
 for entity in &voices{commands.entity(entity).despawn();}
 for o in &game.project.objects{if let Some(s)=&o.pro.sound{if !forge_engine::valid_asset(&s.path){continue;}let bus=if s.music{game.project.settings.music}else{game.project.settings.sfx};let volume=(s.volume*bus*game.project.settings.master).clamp(0.,1.);let settings=if s.looping{PlaybackSettings::LOOP}else{PlaybackSettings::DESPAWN};let settings=settings.with_spatial(s.stereo_pan&&!s.music).with_spatial_scale(bevy::audio::SpatialScale::new_2d(0.01));commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(s.path.clone())),Transform::from_xyz(o.position[0],o.position[1],0.),settings.with_volume(bevy::audio::Volume::Linear(volume)).with_speed(s.speed.clamp(0.5,2.)),AudioBus{gain:s.volume,music:s.music,source:o.id,spatial:s.spatial,distance:s.distance,last_volume:-1.}));}}
}
fn tick(mut commands:Commands,assets:Res<AssetServer>,time:Res<Time>,keys:Res<ButtonInput<KeyCode>>,pads:Query<&Gamepad>,hud:Res<HudInput>,mut game:ResMut<Game>,images:Res<Assets<Image>>,mut sprites:Query<(Entity,&ObjectId,&mut Transform,&mut Sprite),Without<Camera2d>>,mut cameras:Query<&mut Transform,With<Camera2d>>){let c=&game.project.settings.production.controls;let pressed=|s:&str,k|keys.pressed(forge_engine::keycode(s,k)) as i32;let mut d=[(pressed(&c.right,KeyCode::KeyD)-pressed(&c.left,KeyCode::KeyA)) as f32,(pressed(&c.up,KeyCode::KeyW)-pressed(&c.down,KeyCode::KeyS)) as f32];for pad in &pads{let dz=c.deadzone.clamp(0.,0.95);let axis=|a|{let v=pad.get(a).unwrap_or(0.);if v.abs()>dz{v}else{0.}};d[0]+=axis(GamepadAxis::LeftStickX);d[1]+=axis(GamepadAxis::LeftStickY);if pad.pressed(GamepadButton::South){d[1]=1.;}}for i in 0..2{d[i]=(d[i]+hud.0[i]).clamp(-1.,1.);}let g=&mut *game;if g.inventory.is_some()&&keys.just_pressed(KeyCode::KeyI){g.inventory_open=!g.inventory_open;}if !g.menu&&keys.just_pressed(KeyCode::KeyE){if let Some(inv)=g.inventory.as_mut(){g.inventory_message=match inv.collect_nearby(&mut g.project){Ok(s)|Err(s)=>s};}}if g.inventory_open{d=[0.;2];}if g.demo.is_none()&&keys.just_pressed(KeyCode::Escape){g.menu=!g.menu;}if g.demo.is_some(){
 if keys.just_pressed(KeyCode::Escape){g.menu=!g.menu;}
 if hud.1 || keys.just_pressed(KeyCode::KeyR){g.project=g.original.clone();if let Some(inv)=&g.inventory{inv.remove_collected(&mut g.project);}#[cfg(feature="audio")] {g.audio_revision=g.audio_revision.wrapping_add(1);}g.sim=Simulation::default();g.demo=Some(forge_engine::DemoSession::default());g.menu=false;g.finished=false;}
 if keys.just_pressed(KeyCode::Enter){g.menu=false;}
 if (hud.2 || keys.just_pressed(KeyCode::KeyN)) && g.demo.as_ref().is_some_and(|d|d.won){if g.campaign && g.level<4 && g.root.join(format!("level{}.forge.json",g.level+1)).is_file() {let next=g.level+1;match Project::load(&g.root.join(format!("level{next}.forge.json"))){Ok(p)=>{if let Err(e)=forge_engine::modules::validate(&p){eprintln!("{e}");return;}g.level=next;g.original=p.clone();g.project=p;if let Some(inv)=&g.inventory{inv.remove_collected(&mut g.project);}#[cfg(feature="audio")] {g.audio_revision=g.audio_revision.wrapping_add(1);}g.sim=Simulation::default();g.demo=Some(forge_engine::DemoSession::default());g.menu=false;},Err(e)=>eprintln!("Level load: {e}")}}else{g.finished=true;}}
 }
 if !g.menu && !g.finished && !g.demo.as_ref().is_some_and(|x|x.won||x.health==0){let dt=time.delta_secs().min(0.033);g.sim.step(&mut g.project,dt,d);if g.demo.is_none()&&keys.just_pressed(KeyCode::KeyJ){if let Some(id)=g.project.objects.iter().find(|o|o.player).map(|o|o.id){forge_engine::combat::strike(&mut g.project,id,if d[0]<0.{-1.}else{1.});}}if let Some(demo)=&mut g.demo{#[cfg(feature="audio")] let old=(demo.score(),demo.health,demo.won);demo.face(d[0]);if keys.just_pressed(KeyCode::KeyJ){demo.attack(&mut g.project);}demo.step(&mut g.project,dt);#[cfg(feature="audio")] let cue=if demo.won&&!old.2{Some("win")}else if demo.health<old.1{Some("hurt")}else if demo.score()>old.0{Some("collect")}else{None};#[cfg(feature="audio")] if let Some(cue)=cue{let path=format!("assets/{cue}.wav");if g.root.join(&path).is_file(){commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(path)),PlaybackSettings::DESPAWN.with_volume(bevy::audio::Volume::Linear((g.project.settings.master*g.project.settings.sfx).clamp(0.,1.)))));}}}}
 let objects:std::collections::HashMap<_,_>=g.project.objects.iter().filter(|o|!o.camera).map(|o|(o.id,o)).collect();let existing:std::collections::HashSet<_>=sprites.iter().map(|(_,id,_,_)|id.0).collect();
 for (entity,id,_,_) in &mut sprites{if !objects.contains_key(&id.0){commands.entity(entity).despawn();}}
 for o in &g.project.objects{if !o.camera&&!existing.contains(&o.id){let mut s=Sprite::from_color(Color::WHITE,Vec2::from_array(o.size));if let Some(path)=&o.sprite{s.image=assets.load(path.clone());}commands.spawn((s,Transform::default(),ObjectId(o.id)));}}for (_,id,mut t,mut s) in &mut sprites{if let Some(o)=objects.get(&id.0).copied(){s.custom_size=Some(Vec2::from_array(o.size));let c=forge_engine::lit_color(o,&g.project);s.color=Color::srgba_u8(c[0],c[1],c[2],c[3]);let p=forge_engine::sprite_center(o,g.project.isometric);t.translation=Vec3::new(p[0],p[1],o.layer as f32*10.+if g.project.isometric{-p[1]*0.001}else{0.});t.rotation=Quat::from_rotation_z(o.rotation.to_radians());if o.sprite.is_some(){if let Some(img)=images.get(&s.image){let uv=o.animation.uv(forge_engine::animation_time(o,g.sim.elapsed));let size=img.size().as_vec2();s.rect=Some(Rect::from_corners(Vec2::from_array(uv[0])*size,Vec2::from_array(uv[2])*size));}}}}if let Some(o)=g.project.objects.iter().find(|o|o.camera){let p=project_point(o.position,g.project.isometric);for mut t in &mut cameras{t.translation.x=p[0];t.translation.y=p[1];}}}

#[derive(Component)] struct ParticleVisual;
fn particle_render(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>,mut old:Query<(Entity,&mut Sprite,&mut Transform),With<ParticleVisual>>){let mut pool=old.iter_mut();let mut count=0;#[cfg(feature="lighting")] let gpu=forge_engine::gpu_particles::selected(&game.project);for o in &game.project.objects{#[cfg(feature="lighting")] if gpu.contains(&o.id){continue;}for (p,size,c) in forge_engine::particles(o,game.sim.elapsed){if count>=4096{break;}count+=1;let p=project_point(p,game.project.isometric);let mut sprite=Sprite::from_color(Color::srgba_u8(c[0],c[1],c[2],c[3]),Vec2::splat(size));if let Some(path)=&o.production.particle_texture{if path.starts_with("assets/"){sprite.image=assets.load(path.clone());}}let t=Transform::from_xyz(p[0],p[1],o.layer as f32*10.+1.);if let Some((_,mut s,mut tr))=pool.next(){*s=sprite;*tr=t;}else{commands.spawn((ParticleVisual,sprite,t));}}}for (e,_,_) in pool{commands.entity(e).despawn();}}

fn hud(mut contexts:EguiContexts,game:ResMut<Game>,mut input:ResMut<HudInput>){let mut game=game;let mut toggle_pause=false;input.0=[0.;2];input.1=false;input.2=false;let Ok(ctx)=contexts.ctx_mut()else{return;};if let Some(d)=&game.demo{egui::Area::new(egui::Id::new("demo_hud")).fixed_pos(egui::pos2(24.,20.)).show(ctx,|ui|{egui::Frame::window(ui.style()).show(ui,|ui|{ui.heading("FORGE / SIGNAL LOST");ui.label(format!("ENERGY CORES  {} / {}",d.score(),forge_engine::DemoSession::total(&game.project)));ui.label(format!("SECTOR {}  |  HEALTH {} / 3",game.level,d.health));ui.label(if game.finished {"CAMPAIGN COMPLETE"}else if d.won {"SECTOR COMPLETE  |  N to continue"}else if d.health==0{"SIGNAL LOST  |  R to retry"}else{"A / D move · W jump · J attack · Esc menu"});if d.won&&!game.finished && ui.button("Continue").clicked(){input.2=true;}if d.health==0 && ui.button("Retry").clicked(){input.1=true;}});});if game.menu{egui::Window::new("SIGNAL LOST").anchor(egui::Align2::CENTER_CENTER,[0.,0.]).collapsible(false).resizable(false).show(ctx,|ui|{ui.heading("SIGNAL LOST / PRO");ui.label("Recover three energy cores and reach the exit.");if ui.button("Start / Restart sector").clicked(){input.1=true;}ui.label("Enter: resume  |  Esc: menu");});}}#[cfg(feature="audio")] if game.menu {egui::Window::new("Audio mixer").show(ctx,|ui|{ui.add(egui::Slider::new(&mut game.project.settings.master,0. ..=1.).text("Master"));ui.add(egui::Slider::new(&mut game.project.settings.music,0. ..=1.).text("Music"));ui.add(egui::Slider::new(&mut game.project.settings.sfx,0. ..=1.).text("SFX"));});}let rect=ctx.screen_rect();for (i,w) in game.project.settings.widgets.iter().enumerate().filter(|(_,w)|game.project.settings.hud_canvas_groups||w.group.trim().is_empty()){let size=forge_engine::adaptive_widget(w,[rect.width(),rect.height()],game.project.settings.production.resolution);let pos=rect.min+egui::vec2(size[0],size[1]);egui::Area::new(egui::Id::new(("hud",i))).fixed_pos(pos).show(ctx,|ui|{if w.action=="label"{if game.project.settings.hud_canvas_groups{ui.add_sized([size[2],size[3]],egui::Label::new(&w.text));}else{ui.label(&w.text);}}else if w.action=="progress"{let value=game.project.objects.iter().find(|o|o.player).and_then(|o|o.pro.variables.get(&w.text)).copied().unwrap_or(0.).clamp(0.,1.);ui.add_sized([size[2],size[3]],egui::ProgressBar::new(value).text(w.text.clone()));}else{let r=ui.add_sized([size[2],size[3]],egui::Button::new(&w.text));if w.action=="pause"&&r.clicked(){toggle_pause=true;}if r.is_pointer_button_down_on(){match w.action.as_str(){"left"=>input.0[0]-=1.,"right"=>input.0[0]+=1.,"jump"=>input.0[1]=1.,_=>{}}}}});}
 if toggle_pause{game.menu=!game.menu;}
 inventory_panel(ctx,&mut game);
 if game.project.settings.hud_canvas_groups{return;}
 let mut groups=std::collections::BTreeMap::<String,HudGroup>::new();for w in &game.project.settings.widgets{let parts=w.group.split('/').map(str::trim).filter(|s|!s.is_empty()).take(8).collect::<Vec<_>>();if let Some((root,rest))=parts.split_first(){groups.entry((*root).into()).or_default().insert(rest,w);}}
 for (name,group) in groups{if let Some(first)=group.first(){let size=forge_engine::adaptive_widget(first,[rect.width(),rect.height()],game.project.settings.production.resolution);let pos=rect.min+egui::vec2(size[0],size[1]);egui::Window::new(name.as_str()).id(egui::Id::new(("hud_group",&name))).default_pos(pos).resizable(true).show(ctx,|ui|group.draw(ui,&mut input));}}

}

#[cfg(feature="audio")] fn mix_audio(time:Res<Time>,game:Res<Game>,mut sinks:Query<(&mut AudioBus,Option<&mut bevy::audio::AudioSink>,Option<&mut bevy::audio::SpatialAudioSink>,&mut Transform),Without<bevy::audio::SpatialListener>>,mut ears:Query<&mut Transform,With<bevy::audio::SpatialListener>>){use bevy::audio::AudioSinkPlayback;let listener=game.project.objects.iter().find(|o|o.player).or_else(||game.project.objects.iter().find(|o|o.camera));let sources:std::collections::HashMap<_,_>=game.project.objects.iter().map(|o|(o.id,o)).collect();if let Some(o)=listener{for mut t in &mut ears{t.translation=Vec3::new(o.position[0],o.position[1],0.);}}for (mut bus,mut sink,mut spatial_sink,mut transform) in &mut sinks {if sink.is_none()&&spatial_sink.is_none(){continue;}let channel=if bus.music{game.project.settings.music}else{game.project.settings.sfx};let source=sources.get(&bus.source).copied();if let Some(o)=source{transform.translation=Vec3::new(o.position[0],o.position[1],0.);}let attenuation=if bus.spatial&&!bus.music{match (source,listener){(Some(a),Some(b))=>forge_engine::sound_attenuation(a.position,b.position,bus.distance),_=>0.}}else{1.};let volume=(bus.gain*channel*game.project.settings.master*attenuation).clamp(0.,1.);let target=if bus.last_volume<0.||volume==0.{volume}else{let k=1.-(-time.delta_secs().clamp(0.,0.1)*18.).exp();let next=bus.last_volume+(volume-bus.last_volume)*k;if (next-volume).abs()<0.002{volume}else{next}};if (target-bus.last_volume).abs()>0.0001 || (target==0. && bus.last_volume!=0.){if let Some(s)=sink.as_mut(){s.set_volume(bevy::audio::Volume::Linear(target));}if let Some(s)=spatial_sink.as_mut(){s.set_volume(bevy::audio::Volume::Linear(target));}bus.last_volume=target;}}}

#[derive(Default)] struct HudGroup<'a>{widgets:Vec<&'a forge_engine::Widget>,children:std::collections::BTreeMap<String,HudGroup<'a>>}
impl<'a> HudGroup<'a>{
 fn insert(&mut self,path:&[&str],widget:&'a forge_engine::Widget){if let Some((head,tail))=path.split_first(){self.children.entry((*head).into()).or_default().insert(tail,widget);}else{self.widgets.push(widget);}}
 fn first(&self)->Option<&'a forge_engine::Widget>{self.widgets.first().copied().or_else(||self.children.values().find_map(|c|c.first()))}
 fn draw(&self,ui:&mut egui::Ui,input:&mut HudInput){for w in &self.widgets{if w.action=="label"{ui.label(&w.text);}else{let r=ui.button(&w.text);if r.is_pointer_button_down_on(){match w.action.as_str(){"left"=>input.0[0]-=1.,"right"=>input.0[0]+=1.,"jump"=>input.0[1]=1.,_=>{}}}}}for (name,child) in &self.children{ui.collapsing(name.as_str(),|ui|child.draw(ui,input));}}
}

#[cfg(feature="lighting")]
fn gpu_scene_sync(game:Res<Game>,mut draw:forge_engine::gpu_scene::GpuDraw,mut sprites:Query<(Entity,&ObjectId,&Sprite,&Transform,&mut Visibility)>){
 if (!game.project.settings.gpu_lighting||game.project.isometric)&&draw.idle(){return;}
 let objects:std::collections::HashMap<_,_>=game.project.objects.iter().map(|o|(o.id,o)).collect();
 draw.sync(&game.project,Some(&game.root),game.sim.elapsed,sprites.iter_mut().filter_map(|(entity,id,s,t,v)|objects.get(&id.0).map(|o|(entity,*o,s,t,v))));
}

#[cfg(feature="lighting")]
fn gpu_particles_sync(game:Res<Game>,time:Res<Time>,mut draw:forge_engine::gpu_particles::ParticleDraw){draw.sync(&game.project,Some(&game.root),if game.menu{0.}else{time.delta_secs()});}

fn inventory_panel(ctx:&egui::Context,game:&mut Game){
 if game.inventory.is_none(){return;}
 egui::Area::new(egui::Id::new("inventory_toggle22")).anchor(egui::Align2::RIGHT_TOP,[-12.,12.]).show(ctx,|ui|{if ui.button("Inventory [I]").clicked(){game.inventory_open=!game.inventory_open;}if !game.inventory_open&&!game.inventory_message.is_empty(){ui.small(&game.inventory_message);}});
 if !game.inventory_open{return;}
 let mut open=game.inventory_open;let mut action=None;let mut save=false;let mut load=false;
 egui::Window::new("Inventory").open(&mut open).show(ctx,|ui|{
  ui.label("E: collect nearby · drag or select two slots to move/merge");
  let inv=game.inventory.as_ref().unwrap();
  egui::Grid::new("forge_inventory_slots22").spacing([5.,5.]).show(ui,|ui|{for (i,slot) in inv.slots.iter().enumerate(){let label=slot.as_ref().map(|s|format!("{} ×{}",s.item,s.count)).unwrap_or_else(||format!("Slot {}",i+1));let response=ui.add_sized([100.,46.],egui::Button::new(label).selected(game.inventory_selected==Some(i)).sense(egui::Sense::click_and_drag()));if slot.is_some(){response.dnd_set_drag_payload(i);}if let Some(from)=response.dnd_release_payload::<usize>(){action=Some((*from,i));game.inventory_selected=None;}else if response.clicked(){if let Some(from)=game.inventory_selected.take(){if from!=i{action=Some((from,i));}}else if slot.is_some(){game.inventory_selected=Some(i);}}if i%4==3{ui.end_row();}}});
  ui.horizontal(|ui|{save=ui.button("Save inventory").clicked();load=ui.button("Load inventory").clicked();});ui.label(&game.inventory_message);
 });game.inventory_open=open;
 if let Some((a,b))=action{if let Some(inv)=game.inventory.as_mut(){inv.move_slot(a,b);}}
 let path=game.root.join("inventory-save.json");
 if save{game.inventory_message=match game.inventory.as_ref().unwrap().save(&path){Ok(())=>"Inventory saved".into(),Err(e)=>e};}
 if load{match forge_engine::Inventory::load(&path){Ok(inv)=>{if inv.slots.len()!=game.inventory.as_ref().unwrap().slots.len(){game.inventory_message="Save slot count differs".into();}else{let original=game.original.objects.iter().filter(|o|o.pro.pickup.is_some()&&!inv.collected.contains(&o.id)).cloned().collect::<Vec<_>>();inv.remove_collected(&mut game.project);for o in original{if !game.project.objects.iter().any(|x|x.id==o.id){game.project.objects.push(o);}}game.inventory=Some(inv);game.inventory_selected=None;game.inventory_message="Inventory loaded".into();}},Err(e)=>game.inventory_message=e}}
}
